ult;         }          function highlightMarkdown(code) {             let result = code.replace(/^#\s+/gm, '<span class="header">$&</span>');             return result;         }          // Toggle dark mode         function toggleDarkMode() {             isDarkMode = !isDarkMode;             document.body.classList.toggle('dark-mode', isDarkMode);             darkModeToggle.textContent = isDarkMode ? 'Light Mode' : 'Dark Mode';         }          // Toggle word wrap         function toggleWordWrap() {             isWordWrap = !isWordWrap;             editor.style.whiteSpace = isWordWrap ? 'pre-wrap' : 'pre';             wordWrapToggle.classList.toggle('active', isWordWrap);         }          // Toggle search modal         function toggleSearch() {             searchModal.style.display = searchModal.style.display === 'block' ? 'none' : 'block';         }          // Event Listeners         editor.addEventListener('input', () => {             updateLineNumbers();             updatePreview();             saveCode();         });          languageSelect.addEventListener('change', updatePreview);          darkModeToggle.addEventListener('click', toggleDarkMode);          wordWrapToggle.addEventListener('click', toggleWordWrap);          searchToggle.addEventListener('click', toggleSearch);          closeSearchButton.addEventListener('click', () => {             searchModal.style.display = 'none';         });          searchButton.addEventListener('click', () => {             const searchTerm = searchInput.value;             if (searchTerm) {                 // This is a very basic search, not replacing the actual editor content                 alert(`Searching for "${searchTerm}"`);             }         });          replaceButton.addEventListener('click', () => {             const searchTerm = searchInput.value;             const replaceTerm = replaceInput.value;             if (searchTerm && replaceTerm) {                 const newCode = editor.value.replace(new RegE