");         exit(EXIT_FAILURE);     }      libevdev_free(device);     return ui; }  static void udp_server(void) {     int sockfd;     struct sockaddr_in serv_addr, cli_addr;     socklen_t cli_len = sizeof(cli_addr);     char buffer[BUFFER_SIZE];      sockfd = socket(AF_INET, SOCK_DGRAM, 0);     if (sockfd < 0) {         perror("ERROR opening socket");         exit(1);     }      memset(&serv_addr, 0, sizeof(serv_addr));     serv_addr.sin_family = AF_INET;     serv_addr.sin_addr.s_addr = INADDR_ANY;     serv_addr.sin_port = htons(PORT);      if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {         perror("ERROR on binding");         exit(1);     }      while (1) {         int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *) &cli_addr, &cli_len);         if (n < 0) {             perror("ERROR in recvfrom");         } else {             int event_index, event_value;             memcpy(&event_index, buffer, sizeof(int));             memcpy(&event_value, buffer + sizeof(int), sizeof(int));              if (event_index >= 0 && event_index < sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0])) {                 libevdev_uinput_write_event(controller, REGISTERED_EVENTS[event_index].type,                                             REGISTERED_EVENTS[event_index].code, event_value);                 libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);             }         }     }      close(sockfd); }  int main() {     controller = controller_create();     udp_server();     libevdev_uinput_destroy(controller);     return 0; } ``` Here is client code: ```zig const std = @import("std"); const rl = @import("raylib"); const net = std.net; const posix = std.posix; const mem = std.mem;  // Define your controller event indices based on the JSON mapping const ControllerEvents = enum(i16) {     ANALOG_LX = 0,     ANALOG_LY = 1,     ANALOG_RX = 2,     ANALOG_RY = 3,     L1 = 4,     L2 = 5,     R1 = 6,     R2 = 7,     TRIANGLE =